INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'Economics', 'Unit 3', 'Molarum Grade 10 — Economics Unit 3: Theory of Production and Cost', 'Source-grounded Molarum Grade 10 Economics questions for Unit 3: Theory of Production and Cost.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('811bbaf2-d6f8-4112-877a-b0c1f6153f96'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What does the textbook describe production as?', 'Transforming inputs into desired outputs by adding economic value', 'Production transforms raw materials and other inputs into outputs while adding economic value.', 0),('58ad72a2-a7a9-419d-8495-47cb9e8c883c'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What does a production function show?', 'The highest output a firm can produce from each specified input combination', 'The production function states the highest output available for a given combination of inputs.', 1),('57eeb5b3-d1ac-42d2-82eb-72ea2cb1906f'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'In the expression Q = f(L, K), what do L and K represent?', 'Labor and capital', 'The textbook uses labor L and capital K as the two inputs in Q = f(L, K).', 2),('61bfc27f-8c82-44d0-87ec-8ebb571033d1'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What condition defines the short run in production?', 'At least one factor of production is fixed', 'The source defines the short run as a period during which at least one factor is fixed.', 3),('4570e90b-e59a-4aa9-8d79-288388b8342f'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'In the long run, what can a firm change according to the textbook?', 'The quantities of all inputs', 'The long run is long enough for all input quantities to be variable.', 4),('c6c8e750-97fb-4f4c-8c05-249dd2d87d8b'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'How is average product of labor calculated?', 'Total product divided by number of workers', 'Average product of labor equals total product divided by the number of workers.', 5),('f0bf3226-45f4-427f-8833-1843a55cdc15'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What is marginal product?', 'Additional output from one extra unit of variable input', 'Marginal product is the extra output obtained with one additional unit of the variable input while other inputs remain constant.', 6),('2c036593-18e2-4fa7-8e60-a2ebde201c4b'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What is the relationship between marginal product and the slope of the total product curve?', 'Marginal product equals the slope of total product', 'The textbook states that marginal product is equal to the slope of total product.', 7),('30bfcfde-6e6b-4766-8977-53be7f946f7a'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What eventually happens when additional labor is added while capital remains fixed?', 'The marginal contribution of extra labor eventually declines', 'The law of diminishing marginal productivity says the marginal contribution of added labor eventually falls when capital is fixed.', 8),('c805e4a7-c6af-435b-8645-831b8a39d361'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'Which description matches Stage II of production?', 'Marginal product is positive but decreasing', 'The text defines Stage II as the range in which marginal product is positive but decreasing.', 9),('332d9346-8783-40ce-8e31-827e6b24a12b'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'When total product is falling, what is true of marginal product?', 'It is negative', 'When total product falls, marginal product becomes negative according to the production-curve relationship.', 10),('adf0f9da-2f2a-47e7-8329-c2ee5d148d39'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What does an isoquant show?', 'Efficient input combinations that yield the same output', 'An isoquant shows possible efficient combinations of inputs that yield an equal level of output.', 11),('969491c7-671d-490a-84a8-f4b53d06a94a'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'Why are isoquants downward sloping according to the textbook?', 'More of one input requires less of the other for the same output', 'A downward-sloping isoquant indicates that more of one factor allows less of the other while holding output constant.', 12),('3115092b-9e3c-45b5-8da8-8e45dc1e0b48'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What is increasing returns to scale?', 'Output rises by more than the proportional increase in all inputs', 'Increasing returns to scale occur when scaling all inputs by a proportion increases output by more than that proportion.', 13),('53dbfcdd-241f-4af9-8242-aa4c416b0825'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What does technological progress allow a firm to do with the same labor and capital combination?', 'Produce more output', 'Technical progress makes production more efficient, allowing higher output from the same input combination.', 14),('0fa1b11d-b077-43c3-8c01-3930ea9f2b2e'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What are prices of inputs or expenditures on inputs called?', 'Cost of production', 'The textbook refers to input prices or expenditures on inputs as the cost of production.', 15),('13e80ef7-6a1a-4ed3-8f28-ee43d8b74413'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'Which cost does not vary with the level of output?', 'Total fixed cost', 'Total fixed cost is independent of output and does not change as quantity changes.', 16),('4f2fc700-bc3d-4b4d-80dc-952005673adb'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'Which example is identified as a variable cost?', 'Cost of raw materials', 'The source lists raw materials and labor as examples of costs that vary with output.', 17),('ffd95989-80f9-4523-83fc-21f561679831'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'Which equation gives total cost?', 'TC = TFC + TVC', 'Total cost is the sum of total fixed cost and total variable cost.', 18),('f3059961-04c3-4b0a-8adb-2f8c27d38b96'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'multiple_choice', 'What relationship between marginal cost and average cost curves is described in the textbook?', 'The MC curve passes through the minimum points of AVC and ATC', 'The source states that MC passes through the minimum points of both AVC and ATC.', 19),('f48589d7-1504-4142-87dc-46b05ab3e920'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'true_false', 'In the long run, there are no fixed costs because all factors can be varied.', 'True', 'The textbook states that all factors can vary in the long run, so there are no fixed costs.', 20),('58bdc1f6-a89e-4dc8-8e7f-ab15a0b36c1d'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'true_false', 'Isoquants can cross each other.', 'False', 'One listed property is that isoquants do not cross each other.', 21),('da218de6-12a8-4912-8e7e-eb2f445bc38b'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'true_false', 'Stage III of production is characterized by negative marginal product.', 'True', 'The source defines Stage III as the range of negative marginal product or decreasing total product.', 22),('bb2781ca-9388-48d0-809d-209f927ecb39'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'true_false', 'When average or marginal product rises, average or marginal cost falls.', 'True', 'The textbook describes product and cost curves as mirror images: rising AP or MP corresponds to falling AC or MC.', 23),('114491ed-2e0f-48e8-8377-ed6a0cdbb9f1'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'State the difference between the short run and the long run in production.', 'In the short run at least one factor is fixed; in the long run all input quantities are variable.', 'The distinction depends on whether all factors can be changed.', 24),('cec09d33-c1fb-4d99-8a4d-8fc75e8aabb3'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'Name the three basic production-function concepts listed in the textbook.', 'Total product, average product, and marginal product.', 'The source lists total product, average product, and marginal product as the three basic concepts.', 25),('01f47140-9e8c-49a4-8145-5bf643493d77'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'What does MRTS of labor for capital describe?', 'The amount capital can be reduced when one extra unit of labor is used while output remains constant.', 'MRTS measures the substitution rate between labor and capital along an isoquant.', 26),('9bc93b97-4868-414a-8bc0-9ec3bb34e198'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'Define constant returns to scale.', 'It occurs when increasing all inputs by a proportion m increases output by the same proportion m.', 'With constant returns to scale, the size of operation does not change factor productivity.', 27),('2cbe45bf-073a-48d8-8b26-11f72ab8d721'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'How does technical progress shift the production function?', 'It shifts the production function upward, allowing more output from the same inputs or the same output from fewer inputs.', 'Technical progress increases production efficiency.', 28),('ae7626a2-dcb5-41d9-8ef4-d4ed005f257c'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'Distinguish total fixed cost from total variable cost.', 'Total fixed cost does not vary with output, while total variable cost varies directly as output changes.', 'Fixed costs are output-independent; variable costs rise or fall with output.', 29),('51428e0b-b4c1-44ab-8fe6-3210cadef759'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'State the relationship between ATC, AFC, and AVC.', 'ATC equals AFC plus AVC.', 'Average total cost is the sum of average fixed cost and average variable cost at each output level.', 30),('536aee8f-3b42-4fff-8104-df444d644ef9'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'What does the economies-of-scale range of the long-run average cost curve mean?', 'It is the range left of the LAC minimum where output can be doubled for less than a doubled cost.', 'The source defines economies of scale using a less-than-proportional rise in cost when output doubles.', 31),('5fe00890-1ba6-4412-8c64-89725860dbf5'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'In the wheat production table, what is total product when 5 units of labor are used?', '40 quintals', 'The table gives total product of 40 quintals for 5 units of labor.', 32),('7dfe3182-6f56-4046-840d-30fc61f0b10c'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'In the wheat production table, what is marginal product when labor increases to 4 units?', '11 quintals', 'At 4 units of labor, the table reports a marginal product of 11 quintals.', 33),('870c9005-2968-456c-88b3-80912a74872a'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'In the wheat production table, what is average product at 3 units of labor?', '6.33 quintals', 'The table lists average product as 6.33 quintals when labor is 3 units.', 34),('1b63db1a-a022-4223-8015-2b14b87dd54c'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'In isoquant combination C, how many units of capital are used to produce 100 units of output?', '4 units of capital', 'The isoquant schedule lists combination C as 3 units of labor, 4 units of capital, and 100 units of output.', 35),('b00c9d74-149b-4eb7-8714-2f42423d88ae'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'From the total-cost table, what is total cost at an output of 6 units?', '200 Birr', 'At output 6, total fixed cost is 100 Birr and total variable cost is 100 Birr, giving total cost of 200 Birr.', 36),('98b9c71f-7563-4901-830e-e6d9592c18a8'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'What is average fixed cost at an output of 5 units in the average-cost table?', '20 Birr', 'The table reports average fixed cost of 20 Birr at output 5.', 37),('70dd55b9-62c1-47b5-80ef-38a3390453df'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'What marginal cost does the table report when output rises from 1 to 2 units?', '26 Birr', 'Total cost rises from 130 Birr to 156 Birr, and the table lists marginal cost of 26 Birr at output 2.', 38),('0fef0562-c9a8-41ca-8ba7-3be98f08e374'::uuid, '92e8d146-86b7-4b57-8746-53bf150627d3'::uuid, 'fill_blank', 'What is average total cost at an output of 4 units in the average-cost table?', '46.25 Birr', 'The table gives total cost of 185 Birr at output 4, and reports average total cost of 46.25 Birr.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('45951b5c-accc-43ba-8c20-37b82b6ff6a8'::uuid, '811bbaf2-d6f8-4112-877a-b0c1f6153f96'::uuid, 'Transforming inputs into desired outputs by adding economic value', TRUE, 0),('c16fcac8-0f97-4642-87f1-041b996008c0'::uuid, '811bbaf2-d6f8-4112-877a-b0c1f6153f96'::uuid, 'Setting the price of a good in a market', FALSE, 1),('97599658-1c51-492e-8314-59afada4573d'::uuid, '811bbaf2-d6f8-4112-877a-b0c1f6153f96'::uuid, 'Buying only fixed inputs', FALSE, 2),('ff63f314-15a1-4262-8d06-2cbc1063a9c3'::uuid, '811bbaf2-d6f8-4112-877a-b0c1f6153f96'::uuid, 'Measuring demand at different prices', FALSE, 3),('a57e62a5-d362-41f4-8f86-38c54807bc06'::uuid, '58ad72a2-a7a9-419d-8495-47cb9e8c883c'::uuid, 'The highest output a firm can produce from each specified input combination', TRUE, 0),('c7f74706-c60d-4a81-8e14-f801ee0f29a4'::uuid, '58ad72a2-a7a9-419d-8495-47cb9e8c883c'::uuid, 'The amount consumers demand at each price', FALSE, 1),('25025407-1729-409a-83d9-aea0feba090a'::uuid, '58ad72a2-a7a9-419d-8495-47cb9e8c883c'::uuid, 'The total tax paid by a firm', FALSE, 2),('0ccd8d3b-42d1-47a9-8fe9-651b3b6ced72'::uuid, '58ad72a2-a7a9-419d-8495-47cb9e8c883c'::uuid, 'The equilibrium price of a product', FALSE, 3),('a7a899e0-4323-41cf-81c1-af71f8b08e4e'::uuid, '57eeb5b3-d1ac-42d2-82eb-72ea2cb1906f'::uuid, 'Labor and capital', TRUE, 0),('74e410de-4b82-43f2-88c3-da32942af1c4'::uuid, '57eeb5b3-d1ac-42d2-82eb-72ea2cb1906f'::uuid, 'Land and knowledge', FALSE, 1),('3eebd9be-525b-4f03-8ba5-cf0c9023436f'::uuid, '57eeb5b3-d1ac-42d2-82eb-72ea2cb1906f'::uuid, 'Loss and cost', FALSE, 2),('1ebdf53c-7422-4c95-847e-dedbe53e30ca'::uuid, '57eeb5b3-d1ac-42d2-82eb-72ea2cb1906f'::uuid, 'Labor and quantity', FALSE, 3),('8a7c0643-cfe1-46c6-8c4c-a334fba7fc1e'::uuid, '61bfc27f-8c82-44d0-87ec-8ebb571033d1'::uuid, 'At least one factor of production is fixed', TRUE, 0),('5ef619c3-9e7d-42e5-8bec-a51a98999d26'::uuid, '61bfc27f-8c82-44d0-87ec-8